test('procedures use forward definitions, local variables, recursion and stop',()=>{
 const r=run('niech x 7\\nf 3\\nnp x\\noto f ma: n\\n jeśli n = 0 [stop]\\n niech x n\\n np x\\n f n - 1\\njuż','2d');
 expect(r.error).toBeNull();expect(r.segments.map(s=>s.to[1])).toEqual([3,5,6,13]);
});
test('runtime errors retain strokes and report argument start',()=>{
 expect(run('np 10\\nniech x 0\\nnp (4 / x)','2d')).toMatchObject({segments:[{to:[0,10,0]}],error:{line:3,column:4}});
 expect(run('np 10\\ngrubosc 13','2d')).toMatchObject({segments:[],error:{line:2,column:9}});
});
test('spatial pitch and roll preserve the specified turtle frame',()=>{
 expect(run('pp 90 gora 90 np 20','3d')).toMatchObject({error:null,segments:[{to:[20,0,0]}]});
 expect(run('np 10 gora 90','2d')).toMatchObject({segments:[],error:{line:1,column:7}});
});
test('lexical repeat counter and finishing operations are bounded',()=>{
 expect(run('powtorz 2 [powtorz 2 [np nrpowt]]','2d').segments.map(s=>s.to[1])).toEqual([1,3,4,6]);
 expect(run('powtorz 1 [f]\\noto f\\nnp nrpowt\\njuż','2d').error).toMatchObject({line:3,column:4});
 expect(run('powtorz 10000 []','2d').error).not.toBeNull();
});
test('clear keeps turtle state and controller can restart and step',()=>{
 const r=run('np 20 czysc pw 90 np 5','2d');expect(r.segments).toEqual([{from:[0,20,0],to:[5,20,0],color:'#16866a',width:3}]);
});
