import { Execution } from '../src/interpreter.js';
test('controller steps, pauses, resumes and resets without accumulating strokes',()=>{
 const e=new Execution('np 10 pw 90 np 20','2d');e.step();expect(e.result().segments).toHaveLength(1);e.pause();expect(e.paused).toBe(true);e.resume();expect(e.paused).toBe(false);e.finish();expect(e.result().segments.at(-1).to).toEqual([20,10,0]);e.reset();expect(e.result().segments).toEqual([]);expect(e.finish().segments).toHaveLength(2);
});
test('invalid procedure names never accept legacy parameter punctuation',()=>{
 expect(run('oto :figura\\nnp 10\\njuż\\n:figura','2d').error).not.toBeNull();
});
EOF
bun test"

